}

/**
 * Resolves a single argument for the {@code genericType} using the type variable information for the {@code targetType}.
 */
private static Class<?> resolveArgument(Type argument, Class<?> targetType) {
    if (argument instanceof Class) {
        return (Class<?>) argument;
    } else if (argument instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) argument, targetType);
    } else if (argument instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) argument).getRawType();
    } else if (argument instanceof GenericArrayType) {
        return (Class<?>) ((GenericArrayType) argument).getGenericComponentType();
    } else {
        return null;
    }
}

/**
 * Resolves a type variable using the type variable information for the {@code targetType}.
 */
private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return Object.class;
    }
    Type bound = bounds[0];
    if (bound instanceof Class) {
        return (Class<?>) bound;
    } else if (bound instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) bound, targetType);
    } else {
        return null;
    }
}

