public static String applyRelativePath(String path, String relativePath) {
    String[] pathSegments = path.split("/");
    String[] relativePathSegments = relativePath.split("/");

    int pathSegmentsLength = pathSegments.length;
    int relativePathSegmentsLength = relativePathSegments.length;

    for (int i = 0; i < relativePathSegmentsLength; i++) {
        String segment = relativePathSegments[i];

        if (segment.equals(".")) {
            continue;
        } else if (segment.equals("..")) {
            if (pathSegmentsLength > 1) {
                pathSegmentsLength -= 2;
                pathSegments = Arrays.copyOf(pathSegments, pathSegmentsLength);
            }
        } else {
            pathSegments = Arrays.copyOf(pathSegments, pathSegmentsLength + 1);
            pathSegments[pathSegmentsLength] = segment;
            pathSegmentsLength++;
        }
    }

    return String.join("/", pathSegments);
}
